/**
 * @method
 * @name txb_IsuNm_onkeypress
 * @description txb_IsuNm onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_IsuNm_onkeypress = function() {
    try {
        if (window.event.keyCode === 13) {
            scwin.fn_GetPar = scwin.getParListBndIsu;
            scwin.fn_SetPar = scwin.setParListBndIsu;
            $c.bns.fn_PopListBndIsuSearch(btn_ISU_CD_SEARCH);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS23400.txb_IsuNm_onkeypress" });
    }
};

