/**
 * @method
 * @name image_1_onclick
 * @description 「접수/처리」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.image_1_onclick = function() {
    try {
        // 접수/처리 버튼 클릭...
        if (dts_List1.getRowCount() < 1) {
            return;
        }
        let std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
        const procs_tp = dts_List1.getCellData(dts_List1.getRowPosition(), "PROCS_TP"); // 처리현황

        const url = "/bnsisuchg/ULDBNS15100.gfm?STD_CD=" + std_cd + "&PROCS_TP=" + procs_tp;
        $c.frame.path("../").GWinOpen("BNS15100", url, "FRN변동금리 변경_BNS15100", 0, 0, 1300, 800, "");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS23400.image_1_onclick" });
    }
};

