/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        if (dts_List1.getRowCount() > 0) {
            scwin.excelDown();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS23400.btn_Excel_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description 권리행사(주식관련채권) 신고내역 조회
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    // 데이터셋 초기화
    dts_List2.removeAll();
    dts_List3.removeAll();
    let param = '';
    param += "&{P}V_ISUR_CD=" + txb_IsurCd.getValue(); // 발행기관코드
    param += "&{P}V_ISUR_NM=" + txb_IsurNm.getValue(); // 발행기관명
    param += "&{P}V_STD_CD=" + txb_StdCd.getValue(); // 표준코드
    param += "&{P}V_ISU_NM=" + txb_IsuNm.getValue(); // 종목명
    param += "&{P}V_PROCS_TP=" + cmb_ProcsTp.getValue(); // 처리구분

    let dsNm = 'BNS_FRN_DECL_DTL_LIST';
    let qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnDeclDtlList';
    $c.bns.fn_SearchBns("ULDBNS23400.xml", dts_List1, dsNm, qryId, param);
};

/**
 * @method
 * @name search1
 * @description 권리행사내역(주식관련사채) 조회
 * @returns {void}
 * @hidden N
 */
scwin.search1 = function() {
    if (dts_List1.getRowPosition() < 1) return;
    let std_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "STD_CD");
    let dsNm = 'BNS_FRNIDS_SCD_LIST';
    let qryId = 'lds.stf.bnsfrn_mgr.select.selectFrnidsScdList';
    let param = '';
    param += '&{P}V_STD_CD=' + std_cd;
    $c.bns.fn_SearchBns("ULDBNS23400.xml", dts_List2, dsNm, qryId, param);
};

/**
 * @method
 * @name search2
 * @description 채권신고담당자 조회
 * @returns {void}
 * @hidden N
 */
scwin.search2 = function() {
    if (dts_List1.getRowPosition() < 1) return;
    const isur_cd = dts_List1.getCellData(dts_List1.getRowPosition(), "ISUR_CD");
    let dsNm = 'BNS_BND_DECL_CHRG_LIST';
    let qryId = 'lds.stf.bnsdecl_mgr.select.selectBndDeclChrgList';
    let param = '&{P}V_ISUR_CD=' + isur_cd;
    $c.bns.fn_SearchBns("ULDBNS23400.xml", dts_List3, dsNm, qryId, param);
};

/**
 * @method
 * @name getParListBndIsu
 * @description 상장종목 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParListBndIsu = function(arrPar) {
    arrPar[0] = {
        LIST_TYPE_CD: "1" // 1 : 상장종목만, 2 : 상장폐지도 포함, else : 모두
            ,
        ISUR_NM: "",
        ISU_NM: txb_IsuNm.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParListBndIsu
 * @description 상장종목 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParListBndIsu = function(arrPar) {
    txb_StdCd.setValue(arrPar[0].STD_CD);
    txb_IsuNm.setValue(arrPar[0].ISU_NM);
};

/**
 * @method
 * @name showIsurPopup
 * @description 발행기관 팝업을 보여준다.
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.showIsurPopup = function(obj) {
    scwin.fn_GetPar = scwin.getParIsurCd;
    scwin.fn_SetPar = scwin.setParIsurCd;
    $c.bns.fn_PopIsurSearch(obj);
};

/**
 * @method
 * @name getParIsurCd
 * @description 발행기관 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: txb_IsurCd.getValue(),
        ISUR_NM: txb_IsurNm.getValue()
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsurCd
 * @description 발행기관 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsurCd = function(arrPar) {
    txb_IsurCd.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm.setValue(arrPar[0].ISUR_NM);
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    // 엑셀 로그
    $c.stf.doLogSave("ULDBNS23400.xml", SCREN_PROCS_TP_CD_07);
    const fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_FRN금리신고관리.xls";
    $c.data.downloadGridViewOffice(grd_List1, "Sheet1", "", 8, 0);
};
